(function(){const B=window.VB_BARRIERS,D=window.VB_DATA;D.barriers=D.barriers.map(item=>({...item,...B.items[item.id],requiresCriteria:false,manualRevision:B.revision,legacyScores:[],scoring:{en:B.items[item.id].criteria.map(c=>c.score+": "+c.en).join("\n"),ar:B.items[item.id].criteria.map(c=>c.score+": "+c.ar).join("\n")}}));})();
